insert into public.events (id, title, short_title, category, start_date, end_date, description, summary, price_label, audience, link_url, image_url, legacy_visual_key, status, display_order) values
('open1', 'Open 27.1', 'Open 27.1', 'Sport Events', '2027-02-18', '2027-02-22', 'Le CrossFit Open démarre à CrossFit Léman ! Premier workout de la saison, première occasion de se challenger et de partager l’énergie des Open avec les autres athlètes de la box. Chacun participe à son niveau, encourage les autres et contribue à l’ambiance collective.', 'Le CrossFit Open démarre à CrossFit Léman ! Premier workout de la saison, première occasion de se challenger et de partager l’énergie des Open avec les autres athlètes de la box', 'Payant', 'Membres CFL', 'https://games.crossfit.com/open', null, 'crossfit', 'published', 0),
('open2', 'Open 27.2', 'Open 27.2', 'Sport Events', '2027-02-25', '2027-03-01', 'Deuxième rendez-vous des CrossFit Open 2027 : un nouveau workout à découvrir, des stratégies à adapter et de nouveaux défis à relever. On se retrouve à la box pour performer, s’encourager et vivre ensemble cette compétition internationale.', 'Deuxième rendez-vous des CrossFit Open 2027 : un nouveau workout à découvrir, des stratégies à adapter et de nouveaux défis à relever', 'Payant', 'Membres CFL', 'https://games.crossfit.com/open', null, 'crossfit', 'published', 1),
('open3', 'Open 27.3', 'Open 27.3', 'Sport Events', '2027-03-04', '2027-03-08', 'Dernière semaine des CrossFit Open 2027. Une ultime épreuve pour donner le meilleur de soi-même, soutenir les autres membres et célébrer le chemin parcouru tout au long des trois semaines.', 'Dernière semaine des CrossFit Open 2027', 'Payant', 'Membres CFL', 'https://games.crossfit.com/open', null, 'crossfit', 'published', 2),
('disco', 'Open Disco Night', 'Disco Night', 'Community Events', '2027-03-06', '2027-03-06', 'Pour clôturer les Open comme il se doit, CrossFit Léman organise l’Open Disco Night ! Après les workouts, place à l’apéro, au repas et à la fête. Une soirée pour se retrouver, célébrer les efforts de chacun et profiter de la communauté.', 'Pour clôturer les Open comme il se doit, CrossFit Léman organise l’Open Disco Night ! Après les workouts, place à l’apéro, au repas et à la fête', 'Gratuit', 'Membres CFL', 'https://events.crossfitleman.ch/', null, '', 'published', 3),
('qf', 'Quarterfinals', 'Quarterfinals', 'Sport Events', '2027-03-15', '2027-03-22', 'Les Quarterfinals marquent une nouvelle étape pour les athlètes qualifiés après les Open. Des workouts exigeants, de la stratégie et du soutien : la box suit et encourage ses compétiteurs dans la suite de leur parcours.', 'Les Quarterfinals marquent une nouvelle étape pour les athlètes qualifiés après les Open', 'Payant', 'Membres CFL', 'https://games.crossfit.com/', null, 'crossfit', 'published', 4),
('lvl3seminar', 'Séminaire CrossFit Level 1', 'Séminaire CF L1', 'Training & Seminars', '2027-04-17', '2027-04-18', 'CrossFit Léman accueille un séminaire officiel CrossFit Level 1 sur deux jours. Une formation dédiée aux fondements de la méthodologie CrossFit, aux mouvements fondamentaux et aux principes du coaching. Les conditions d’accès et d’inscription sont précisées sur le site officiel.', 'CrossFit Léman accueille un séminaire officiel CrossFit Level 1 sur deux jours', 'Payant', 'Membres CFL', 'https://www.crossfit.com/certificate-courses/level-1', null, 'wordmark', 'published', 5),
('cn2', 'Community Night #2', 'CN #2', 'Community Events', '2027-04-30', '2027-04-30', 'Deuxième Community Night de l’année : un nouveau WOD imaginé à partir d’un jeu ou d’un concept inattendu. Formez des équipes, relevez des défis sportifs différents des cours habituels et profitez d’un rendez-vous qui fait vivre la communauté CFL.', 'Deuxième Community Night de l’année : un nouveau WOD imaginé à partir d’un jeu ou d’un concept inattendu', 'Gratuit', 'Membres CFL', 'https://events.crossfitleman.ch/', null, '', 'published', 6),
('murph', 'Murph Day', 'Murph Day', 'Community Events', '2027-05-31', '2027-05-31', 'Murph Day est un rendez-vous communautaire autour du Hero WOD Murph. Chacun relève le défi à son niveau, dans le respect de ses capacités, avec le soutien des autres membres. Une journée de solidarité, d’engagement et de dépassement collectif.', 'Murph Day est un rendez-vous communautaire autour du Hero WOD Murph', 'Gratuit', 'Membres CFL', 'https://events.crossfitleman.ch/', null, 'murph_photo', 'published', 7),
('stc', 'Swiss Team Challenge', 'STCH', 'Sport Events', '2027-06-19', '2027-06-19', 'Le Swiss Team Challenge est une compétition organisée dans de nombreuses box à travers toute la Suisse. Formez une équipe de quatre athlètes, avec au moins une femme et un homme, pour relever plusieurs WODs adaptés à différents niveaux. Pas besoin de voyager : vous participez directement chez CrossFit Léman ! La box vous offre l’inscription afin de vous challenger entre amis, dans une ambiance cool et détendue, et surtout de partager un beau moment ensemble.', 'Le Swiss Team Challenge est une compétition organisée dans de nombreuses box à travers toute la Suisse', 'Gratuit', 'Membres CFL', 'https://www.swissteamchallenge.ch/', null, 'stch', 'published', 8),
('baf2', 'Bring a Friend #2', 'Bring a Friend #2', 'Community Events', '2027-08-23', '2027-08-27', 'Une deuxième occasion d’inviter une amie, un ami ou un proche pour découvrir CrossFit Léman. Partagez un WOD, faites découvrir la communauté et vivez une expérience sportive à deux dans une ambiance accueillante.', 'Une deuxième occasion d’inviter une amie, un ami ou un proche pour découvrir CrossFit Léman', 'Gratuit', 'Membres CFL', 'https://events.crossfitleman.ch/', null, '', 'published', 9),
('alliance', 'The Alliance', 'The Alliance', 'Sport Events', '2027-09-04', '2027-09-04', 'The Alliance est le rendez-vous compétitif interne de CrossFit Léman. Une journée pour se challenger, mettre ses capacités à l’épreuve et partager l’intensité d’une compétition au sein de la box. L’engagement sportif compte autant que les encouragements et les moments partagés.', 'The Alliance est le rendez-vous compétitif interne de CrossFit Léman', 'À confirmer', 'Membres CFL', 'https://events.crossfitleman.ch/', null, 'sabers', 'published', 10),
('cn3', 'Community Night #3 — Will You Escape the Box?', 'CN #3 · Escape', 'Community Events', '2027-10-30', '2027-10-30', 'Will You Escape the Box? Pour Halloween, la box se transforme en terrain de jeu. Cette Community Night mêle un WOD immersif, des défis à résoudre en équipe et une ambiance mystérieuse. Venez découvrir si vous réussirez à vous échapper de la box !', 'Will You Escape the Box? Pour Halloween, la box se transforme en terrain de jeu', 'Gratuit', 'Membres CFL', 'https://events.crossfitleman.ch/', null, '', 'published', 11),
('rowathlon', 'Rowathlon', 'Rowathlon', 'Sport Events', '2027-11-07', '2027-11-07', 'Un marathon sur rameur, un défi collectif et une bonne cause à soutenir ! Le Rowathlon réunit des équipes de CrossFit Léman et d’autres box participantes autour d’un objectif : parcourir les 42,195 km d’un marathon en se relayant sur le rameur. Chaque coup de rame compte. L’essentiel est de contribuer à l’effort commun, de s’encourager et de mettre notre énergie au service d’une cause solidaire.', 'Un marathon sur rameur, un défi collectif et une bonne cause à soutenir ! Le Rowathlon réunit des équipes de CrossFit Léman et d’autres box participantes autour d’un objectif : par', 'À confirmer', 'Membres CFL et sur invitation', 'https://events.crossfitleman.ch/', null, '', 'published', 12),
('christmaswod', 'Christmas WOD', 'Christmas WOD', 'Community Events', '2027-12-23', '2027-12-23', 'Le Christmas WOD rassemble la communauté pour un entraînement de Noël sportif, ludique et festif. Une belle façon de terminer l’année à la box, de partager un dernier défi et de profiter d’un moment convivial ensemble.', 'Le Christmas WOD rassemble la communauté pour un entraînement de Noël sportif, ludique et festif', 'Gratuit', 'Membres CFL', 'https://events.crossfitleman.ch/', null, 'christmas_photo', 'published', 13),
('cn1', 'Community Night #1', 'CN #1', 'Community Events', '2027-01-08', '2027-01-08', 'Une Community Night, ce n’est pas un WOD ordinaire ! On détourne un jeu ou un concept original pour en faire un entraînement collectif ludique, surprenant et accessible aux membres. Effort, stratégie, rires et échanges sont au programme, avec un moment convivial pour prolonger la soirée.', 'Une Community Night, ce n’est pas un WOD ordinaire ! On détourne un jeu ou un concept original pour en faire un entraînement collectif ludique, surprenant et accessible aux membres', 'Gratuit', 'Membres CFL', 'https://events.crossfitleman.ch/', null, '', 'published', 14),
('baf1', 'Bring a Friend #1', 'Bring a Friend #1', 'Community Events', '2027-01-18', '2027-01-22', 'Pendant une semaine, les membres de CrossFit Léman invitent un proche à découvrir leur univers. Une occasion de partager un entraînement, de faire découvrir l’esprit de la box et de vivre ensemble une séance adaptée et conviviale.', 'Pendant une semaine, les membres de CrossFit Léman invitent un proche à découvrir leur univers', 'Gratuit', 'Membres CFL', 'https://events.crossfitleman.ch/', null, '', 'published', 15)
